{"sql": "CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id INTEGER,
    target_inventory_id INTEGER,
    part_to_transfer_num VARCHAR,
    color_to_transfer_id INTEGER,
    quantity_to_transfer INTEGER,
    transfer_reason VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT AS $$
DECLARE
    source_quantity INTEGER;
    target_quantity INTEGER;
    is_spare_flag BOOLEAN;
    error_msg TEXT;
    success_msg TEXT;
BEGIN
    -- Initialize error message
    error_msg := '';

    -- Log the attempt
    INSERT INTO inventory_transfer_log (
        source_inventory_id,
        target_inventory_id,
        part_num,
        color_id,
        quantity_transferred,
        transfer_reason,
        transfer_status
    ) VALUES (
        source_inventory_id,
        target_inventory_id,
        part_to_transfer_num,
        color_to_transfer_id,
        quantity_to_transfer,
        transfer_reason,
        'failed'  -- Default to failed, will update to success if successful
    );

    -- Validation A: Basic Checks
    -- Check if source and target inventories exist
    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE id = source_inventory_id) THEN
        error_msg := 'Source inventory ID ' || source_inventory_id || ' does not exist';
        UPDATE inventory_transfer_log 
        SET error_message = error_msg 
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
        RAISE EXCEPTION '%', error_msg;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE id = target_inventory_id) THEN
        error_msg := 'Target inventory ID ' || target_inventory_id || ' does not exist';
        UPDATE inventory_transfer_log 
        SET error_message = error_msg 
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
        RAISE EXCEPTION '%', error_msg;
    END IF;

    -- Check if part exists
    IF NOT EXISTS (SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num) THEN
        error_msg := 'Part ' || part_to_transfer_num || ' does not exist';
        UPDATE inventory_transfer_log 
        SET error_message = error_msg 
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
        RAISE EXCEPTION '%', error_msg;
    END IF;

    -- Check if color exists
    IF NOT EXISTS (SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id) THEN
        error_msg := 'Color ID ' || color_to_transfer_id || ' does not exist';
        UPDATE inventory_transfer_log 
        SET error_message = error_msg 
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
        RAISE EXCEPTION '%', error_msg;
    END IF;

    -- Prevent self-transfers
    IF source_inventory_id = target_inventory_id THEN
        error_msg := 'Source and target inventory IDs cannot be the same';
        UPDATE inventory_transfer_log 
        SET error_message = error_msg 
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
        RAISE EXCEPTION '%', error_msg;
    END IF;

    -- Validation B: Business Rules
    -- Check quantity limits
    IF quantity_to_transfer < 1 THEN
        error_msg := 'Transfer quantity must be at least 1';
        UPDATE inventory_transfer_log 
        SET error_message = error_msg 
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
        RAISE EXCEPTION '%', error_msg;
    END IF;

    IF quantity_to_transfer > 500 THEN
        error_msg := 'Transfer quantity cannot exceed 500 parts per operation';
        UPDATE inventory_transfer_log 
        SET error_message = error_msg 
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
        RAISE EXCEPTION '%', error_msg;
    END IF;

    -- Start transaction block
    BEGIN
        -- Step A: Pre-validation with locking
        -- Lock both inventory records to prevent race conditions
        SELECT quantity, is_spare INTO source_quantity, is_spare_flag
        FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id 
        AND part_num = part_to_transfer_num 
        AND color_id = color_to_transfer_id
        FOR UPDATE;

        -- Check if source has the part
        IF NOT FOUND THEN
            error_msg := 'Part ' || part_to_transfer_num || ' with color ID ' || color_to_transfer_id || ' not found in source inventory ' || source_inventory_id;
            UPDATE inventory_transfer_log 
            SET error_message = error_msg 
            WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
            RAISE EXCEPTION '%', error_msg;
        END IF;

        -- Check if source has sufficient quantity
        IF source_quantity < quantity_to_transfer THEN
            error_msg := 'Insufficient quantity in source inventory. Available: ' || source_quantity || ', Requested: ' || quantity_to_transfer;
            UPDATE inventory_transfer_log 
            SET error_message = error_msg 
            WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
            RAISE EXCEPTION '%', error_msg;
        END IF;

        -- Step B: Source Inventory Update
        -- Decrease quantity in source inventory
        IF source_quantity = quantity_to_transfer THEN
            -- If quantity becomes zero, delete the row
            DELETE FROM lego_inventory_parts
            WHERE inventory_id = source_inventory_id 
            AND part_num = part_to_transfer_num 
            AND color_id = color_to_transfer_id;
        ELSE
            -- Otherwise, decrease the quantity
            UPDATE lego_inventory_parts
            SET quantity = quantity - quantity_to_transfer
            WHERE inventory_id = source_inventory_id 
            AND part_num = part_to_transfer_num 
            AND color_id = color_to_transfer_id;
        END IF;

        -- Step C: Target Inventory Update
        -- Check if part exists in target inventory
        SELECT quantity INTO target_quantity
        FROM lego_inventory_parts
        WHERE inventory_id = target_inventory_id 
        AND part_num = part_to_transfer_num 
        AND color_id = color_to_transfer_id
        FOR UPDATE;

        IF FOUND THEN
            -- If exists: increase quantity
            UPDATE lego_inventory_parts
            SET quantity = quantity + quantity_to_transfer
            WHERE inventory_id = target_inventory_id 
            AND part_num = part_to_transfer_num 
            AND color_id = color_to_transfer_id;
        ELSE
            -- If not exists: insert new record with same is_spare flag as source
            INSERT INTO lego_inventory_parts (inventory_id, part_num, color_id, quantity, is_spare)
            VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, is_spare_flag);
        END IF;

        -- Step D: Audit Logging
        -- Update the log entry to mark as successful
        UPDATE inventory_transfer_log 
        SET transfer_status = 'success', error_message = NULL
        WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);

        -- Return success message
        success_msg := 'Successfully transferred ' || quantity_to_transfer || ' parts (' || part_to_transfer_num || ', color_id: ' || color_to_transfer_id || ') from inventory ' || source_inventory_id || ' to inventory ' || target_inventory_id || '. Reason: ' || transfer_reason;

        RETURN success_msg;

    EXCEPTION
        WHEN OTHERS THEN
            -- Log the error and re-raise
            error_msg := SQLERRM;
            UPDATE inventory_transfer_log 
            SET error_message = error_msg 
            WHERE log_id = (SELECT MAX(log_id) FROM inventory_transfer_log);
            RAISE;
    END;
END;
$$ LANGUAGE plpgsql;"}

